// Public receive/poll inputs; private visibility is observation only, never mutation.
#define private public
#include "../src/owned/OwnedHost.h"
#undef private
#define main original_owned_fixture_main
#include "test_owned_host.cpp"
#undef main

static void boot_actual(Fixture& f){unsigned limit=0;bool hbs=false;while(!f.host.radioStats().controller_ready&&limit++<1400){f.poll();if(!f.tx.empty()){auto p=f.pop();auto op=Fixture::op(p);if(op==0x0c33){CHECK(p.size()==11&&bth_read_le16(p.data()+4)==1021&&p[6]==BTH_GAP_SYNC_BYTES&&bth_read_le16(p.data()+7)==4&&bth_read_le16(p.data()+9)==BTH_GAP_SYNC_PACKETS);hbs=true;}auto response=f.response(op);if(op==0x2002)response={0,251,0,8};if(op==0x2003)response={0,31,0,0,0,0,0,0,0};f.complete(op,response);}}CHECK(hbs&&f.host.radioStats().controller_ready);f.settle();CHECK(f.host.flow_.le.length==251&&f.host.flow_.le.total==8);}
static uint16_t start_classic(Fixture& f){f.classicConnect();auto signal=f.channel(0x19,0x81);f.acl(0x25,signal,{0x10,3,4,8,1,0,7,6,0,0,0x21,0x15,2,53});f.settle();f.acl(0x25,signal,{0x20,6,4});f.settle();auto media=f.channel(0x19,0x82);f.acl(0x25,signal,{0x30,7,4});f.settle();CHECK(f.playing&&f.host.radioStats().streaming);return media;}
static Bytes value(unsigned seed){Bytes b(512);for(unsigned i=0;i<b.size();++i)b[i]=uint8_t(i*37+seed);return b;}
static Bytes write(const Bytes& data){Bytes p={0x12,9,0};p.insert(p.end(),data.begin(),data.end());return p;}
static void drain(Fixture& f,bool return_le=true){for(unsigned n=0;n<16;++n){f.poll();while(!f.tx.empty()){auto packet=f.pop();if(packet[0]==2){auto handle=bth_read_le16(packet.data()+1)&0xfff;if(handle!=0x26||return_le)f.event(0x13,{1,uint8_t(handle),uint8_t(handle>>8),1,0});}else f.acknowledge(packet);}}}
static void media(Fixture& f,uint16_t cid,unsigned seq){Bytes p={0x80,0x60,uint8_t(seq>>8),uint8_t(seq),1,2,3,4,5,6,7,8,1,0xaa};f.acl(0x25,cid,p);drain(f,false);}
static void inbound(Fixture& f,const Bytes& att,unsigned fragment){Bytes p={uint8_t(att.size()),uint8_t(att.size()>>8),4,0};p.insert(p.end(),att.begin(),att.end());for(size_t pos=0;pos<p.size();pos+=fragment){size_t n=p.size()-pos;if(n>fragment)n=fragment;CHECK(f.host.rx_.outstanding<OwnedHost::RxWindow);f.rawAcl(0x26,pos?1:2,Bytes(p.begin()+pos,p.begin()+pos+n));drain(f);}}
static void setup_ble(Fixture& f){f.leConnect();f.acl(0x26,4,{2,5,2});f.settle();f.acl(0x26,4,{0x12,12,0,1,0});f.settle();CHECK(f.host.bleStats().att_mtu==517&&f.host.bleStats().notify_enabled&&!f.host.rx_.outstanding);}
static void ordinary(unsigned fragment){Fixture f;boot_actual(f);auto cid=start_classic(f);setup_ble(f);auto bytes=value(fragment);unsigned previous=f.media;
 for(unsigned n=0;n<10;++n){inbound(f,write(bytes),fragment);CHECK(f.host.bleStats().writes==n+1&&!f.host.peers_[1].has_pending&&!f.host.rx_.outstanding);BleWrite copied;CHECK(f.host.bleReadWrite(copied)&&copied.length==512&&!memcmp(copied.data,bytes.data(),512));CHECK(f.host.bleNotify(copied.data,copied.length)==Status::Ok);drain(f);media(f,cid,n);CHECK(f.media==previous+n+1&&f.host.radioStats().streaming&&!f.host.rx_.outstanding);}
 CHECK(!f.host.radioStats().transport_errors&&!f.host.bleStats().capacity_retries);printf("Ordinary one-outstanding512 echo, incoming fragment%u:10 copies/Classic progress/no retained RX credits\n",fragment);}
template<class T>static auto drops(const T&s,int)->decltype(s.write_command_drops){return s.write_command_drops;}
template<class T>static unsigned drops(const T&,long){return 0;}
static unsigned command_drops(const Fixture&f){return drops(f.host.bleStats(),0);}
static bool send_bounded(Fixture&f,const Bytes&att,unsigned fragment){Bytes p={uint8_t(att.size()),uint8_t(att.size()>>8),4,0};p.insert(p.end(),att.begin(),att.end());for(size_t pos=0;pos<p.size();pos+=fragment){if(f.host.rx_.outstanding>=4)return false;size_t n=p.size()-pos;if(n>fragment)n=fragment;f.rawAcl(0x26,pos?1:2,Bytes(p.begin()+pos,p.begin()+pos+n));drain(f,false);}return true;}
static void exhaust_tx(Fixture&f,const Bytes&v){for(unsigned i=0;i<3;++i){CHECK(f.host.bleNotify(v.data(),512)==Status::Ok);drain(f,false);}CHECK(!f.host.flow_.le.available);for(unsigned i=0;i<2;++i){CHECK(f.host.bleNotify(v.data(),512)==Status::Ok);drain(f,false);}CHECK(f.host.control_.peers[1].owned==3);}
static void zero_normal_grant(Fixture&f){f.event(0x3e,{6,0x26,0,24,0,24,0,0,0,0xf4,1});bool issued=false;for(unsigned i=0;i<20&&!issued;++i){f.poll();while(!f.tx.empty()){auto p=f.pop();if(p[0]==1&&Fixture::op(p)==0x2020){f.complete(0x2020,{0},0);issued=true;}else f.acknowledge(p);}}CHECK(issued&&f.host.flow_.command_credits==0);}
static bool command_stream(unsigned fragment,bool full_tx){Fixture f;boot_actual(f);auto cid=start_classic(f);setup_ble(f);auto first=value(0);if(full_tx){exhaust_tx(f,first);zero_normal_grant(f);}auto previous=f.media;auto pdus=f.host.bleStats().received_pdus;
 for(unsigned n=0;n<32;++n){auto bytes=value(n);auto p=write(bytes);p[0]=0x52;if(!send_bounded(f,p,fragment)){fprintf(stderr,"POLICY RED:honest globalACL4 blocks command%u before32; no extra packet submitted\n",n);return false;}CHECK(f.host.rx_.outstanding==0&&!f.host.peers_[1].has_pending);media(f,cid,n);CHECK(f.media==previous+n+1&&f.host.radioStats().streaming&&!f.host.radioStats().transport_errors);}
 CHECK(sizeof(BleStats)==40&&f.host.bleStats().writes==1&&command_drops(f)==31&&f.host.bleStats().received_pdus==pdus+32);BleWrite out;CHECK(f.host.bleReadWrite(out)&&out.length==512&&!memcmp(out.data,first.data(),512));CHECK(!f.host.bleReadWrite(out));
 if(full_tx){CHECK(f.host.flow_.command_credits==0&&f.host.flow_.le.available==0&&f.host.control_.peers[1].owned==3);f.event(0x13,{1,0x26,0,8,0});drain(f);CHECK(!f.host.control_.peers[1].owned);}
 printf("32 legal commands fragment%u fullTX%u:old copy preserved/31 drops/realHNC/32Classic callbacks\n",fragment,full_tx);return true;}
static void malformed(){Fixture f;boot_actual(f);setup_ble(f);auto a=value(7);exhaust_tx(f,a);auto accepted=write(a);accepted[0]=0x52;CHECK(send_bounded(f,accepted,1021));auto count=f.host.bleStats().received_pdus;
 std::vector<Bytes> invalid={{0x52},{0x52,9},{0x52,13,0,1},{0x52,0xff,0xff,1},{0x52,12,0,2,0}};Bytes large(516,1);large[0]=0x52;large[1]=9;large[2]=0;invalid.push_back(large);large.resize(518);invalid.push_back(large);
 for(auto&p:invalid){CHECK(send_bounded(f,p,251));CHECK(!f.host.rx_.outstanding&&!f.host.peers_[1].has_pending&&f.host.bleStats().writes==1&&command_drops(f)==0&&f.host.bleStats().notify_enabled);}
 CHECK(f.host.bleStats().received_pdus==count+invalid.size()&&f.host.control_.peers[1].owned==3);BleWrite out;CHECK(f.host.bleReadWrite(out)&&!memcmp(out.data,a.data(),512));CHECK(f.host.radioStats().transport_errors==0);}
static void requests(){Fixture f;boot_actual(f);auto cid=start_classic(f);setup_ble(f);auto a=value(1),b=value(2);inbound(f,write(a),1021);auto before=f.media;f.acl(0x26,4,write(b));drain(f);CHECK(!f.host.peers_[1].has_pending&&f.host.le_.pendingAtt()&&f.host.rx_.outstanding==0&&f.host.bleStats().writes==1&&!command_drops(f));for(unsigned i=0;i<8;++i){media(f,cid,i);CHECK(f.media==before+i+1&&f.host.rx_.outstanding==0);}BleWrite out;CHECK(f.host.bleReadWrite(out)&&!memcmp(out.data,a.data(),512));drain(f);CHECK(!f.host.peers_[1].has_pending&&!f.host.le_.pendingAtt()&&!f.host.rx_.outstanding&&f.host.bleStats().writes==2&&!command_drops(f));CHECK(f.host.bleReadWrite(out)&&!memcmp(out.data,b.data(),512));printf("Conforming acknowledged requests:bounded delayedB,exactA/B,no command drops\n");}
static void mixed_isolation(){Fixture f;boot_actual(f);setup_ble(f);auto a=value(1),b=value(2);inbound(f,write(a),1021);f.acl(0x26,4,write(b));drain(f);CHECK(f.host.le_.pendingAtt()&&!f.host.rx_.outstanding);auto command=write(b);command[0]=0x52;for(unsigned i=0;i<32;++i){CHECK(send_bounded(f,command,251));CHECK(!f.host.rx_.outstanding&&f.host.le_.pendingAtt());}CHECK(!f.host.peers_[1].has_pending&&command_drops(f)==32&&f.host.radioStats().transport_errors==0);BleWrite out;CHECK(f.host.bleReadWrite(out)&&!memcmp(out.data,a.data(),512));drain(f);CHECK(f.host.bleReadWrite(out)&&!memcmp(out.data,b.data(),512));printf("Mixed delayedRequest+commands:independent ATT copy,real RX retired\n");}
static void generation(){Fixture f;boot_actual(f);setup_ble(f);auto a=value(3);auto p=write(a);p[0]=0x52;CHECK(send_bounded(f,p,27));CHECK(send_bounded(f,p,251));CHECK(command_drops(f)==1);auto old=f.host.bleStats().generation;f.event(5,{0,0x26,0,0x13});drain(f);CHECK(!f.host.bleStats().connected);BleWrite out;CHECK(!f.host.bleReadWrite(out));f.leConnect();f.acl(0x26,4,{2,5,2});f.settle();CHECK(f.host.bleStats().generation!=old&&command_drops(f)==1);CHECK(send_bounded(f,p,27));CHECK(f.host.bleReadWrite(out)&&out.generation!=old&&!memcmp(out.data,a.data(),512)&&command_drops(f)==1);f.host.end();CHECK(f.host.begin(f.config,f.hooks)==Status::Ok&&command_drops(f)==0);}
int main(){mixed_isolation();if(!command_stream(1021,false))return 2;CHECK(command_stream(251,false));CHECK(command_stream(27,false));CHECK(command_stream(27,true));malformed();requests();generation();ordinary(1021);ordinary(251);ordinary(27);printf("WriteCommand policy and mixed request isolation %u checks PASS\n",checks);}
